964:   private static final class StopWork {
965:     final AtomicInteger initiated = new AtomicInteger(), finished = new AtomicInteger();
966:     final AtomicReference<Throwable> failure = new AtomicReference<>();
967:     void send(GuidedDispatchService sender, ObjectNode context, String reason) {
968:       initiated.incrementAndGet();
969:       try {
970:         sender.stop(context, reason);
971:       } catch (RuntimeException | Error problem) {
972:         failure.compareAndSet(null, problem);
973:         throw problem;
974:       } finally {
975:         finished.incrementAndGet();
976:       }
977:     }
978:   }
