1068:     synchronized void reopen() throws IOException {
1069:       if (closed) {
1070:         throw new IOException("Case-owned PG route is closed");
1071:       }
1072:       if (listener != null && !listener.isClosed()) {
1073:         return;
1074:       }
1075:       var server = new java.net.ServerSocket();
1076:       try {
1077:         server.setReuseAddress(true);
1078:         server.bind(new InetSocketAddress("127.0.0.1", privatePort));
1079:         privatePort = server.getLocalPort();
1080:         listener = server;
1081:         bridges.submit(() -> accept(server));
