1130:     private void beginTransfer(java.net.Socket from, java.net.Socket to) {
1131:       activeTransfers.incrementAndGet();
1132:       try {
1133:         bridges.submit(() -> transfer(from, to));
1134:       } catch (java.util.concurrent.RejectedExecutionException failure) {
1135:         activeTransfers.decrementAndGet();
1136:         throw failure;
1137:       }
1138:     }
