1140:     private void transfer(java.net.Socket from, java.net.Socket to) {
1141:       byte[] bytes = new byte[8192];
1142:       try {
1143:         int count;
1144:         while ((count = from.getInputStream().read(bytes)) != -1) {
1145:           to.getOutputStream().write(bytes, 0, count);
1146:           to.getOutputStream().flush();
1147:         }
1148:       } catch (IOException disconnected) {
1149:         // JDBC completion and the explicit private route cut close both opaque sides.
1150:       } finally {
1151:         Arrays.fill(bytes, (byte) 0);
1152:         try {
1153:           closeSocket(from);
1154:           closeSocket(to);
1155:         } finally {
1156:           activeTransfers.decrementAndGet();
1157:         }
1158:       }
1159:     }
