1161:     private void closeSocket(java.net.Socket socket) {
1162:       if (socket == null) {
1163:         return;
1164:       }
1165:       try {
1166:         socket.close();
1167:       } catch (IOException failure) {
1168:         closeFailures.add(failure);
1169:       } finally {
1170:         if (socket.isClosed()) { sockets.remove(socket); }
1171:       }
1172:     }
