1174:     synchronized void unavailable() throws IOException {
1175:       IOException listenerFailure = null;
1176:       java.net.ServerSocket previous = listener;
1177:       listener = null;
1178:       if (previous != null) {
1179:         try { previous.close(); }
1180:         catch (IOException failure) {
1181:           listenerFailure = failure;
1182:           if (!previous.isClosed()) { listener = previous; }
1183:         }
1184:       }
1185:       // Continue socket cleanup even if closing the listener failed.
1186:       for (var socket : sockets.toArray(java.net.Socket[]::new)) { closeSocket(socket); }
1187:       if (listenerFailure != null) { throw listenerFailure; }
1188:     }
