1561:     require(parts.length == 3, "UNAUTHENTICATED", 401);
1562:     var decoder = Base64.getUrlDecoder();
1563:     var signature = Signature.getInstance("SHA256withRSA");
1564:     signature.initVerify(ISSUER.getPublic());
1565:     signature.update((parts[0] + "." + parts[1]).getBytes(StandardCharsets.US_ASCII));
